-- n-plus-one-fixed: Authors with their posts, two queries in total (the fix).
-- SQL captured from each approach by the tests. Generated file, do not edit.

-- raw (2 statements)
SELECT id, name FROM authors ORDER BY id ASC LIMIT $1;

SELECT author_id AS "authorId", title FROM posts WHERE author_id = ANY($1::int[]) ORDER BY id ASC;

-- prisma (2 statements)
SELECT "public"."authors"."id", "public"."authors"."name" FROM "public"."authors" WHERE 1=1 ORDER BY "public"."authors"."id" ASC LIMIT $1 OFFSET $2;

